{"content": "import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import fs from 'fs';

const __dirname = dirname(fileURLToPath(import.meta.url));

const app = express();
app.use(cors());
app.use(express.json());

// PGLite data directory
const dataDir = join(__dirname, '..', '.kanban-data');
if (!fs.existsSync(dataDir)) {
  fs.mkdirSync(dataDir, { recursive: true });
}

let db;
let clients = []; // SSE client writers

// SSE broadcast helper
function broadcast(event, data) {
  const payload = JSON.stringify({ event, data });
  clients.forEach((writer) => {
    try {
      writer.write(`event: ${event}\ndata: ${payload}\n\n`);
    } catch (e) {
      // Client disconnected
    }
  });
}

// Initialize database
async function initDb() {
  db = await PGlite.create({
    dataDir: join(dataDir, 'pglite-data'),
  });

  await db.exec(`
    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      position REAL NOT NULL
    );

    CREATE TABLE IF NOT EXISTS cards (
      id TEXT PRIMARY KEY,
      column_id TEXT NOT NULL REFERENCES columns(id),
      text TEXT NOT NULL,
      position REAL NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

    CREATE INDEX IF NOT EXISTS idx_cards_column_position ON cards(column_id, position);
  `);

  // Seed default columns if empty
  const count = await db.sql`SELECT COUNT(*) as count FROM columns`;
  if (count[0].count === 0) {
    const cols = [
      { id: crypto.randomUUID(), title: 'To Do', position: 1 },
      { id: crypto.randomUUID(), title: 'In Progress', position: 2 },
      { id: crypto.randomUUID(), title: 'Done', position: 3 },
    ];
    for (const col of cols) {
      await db.sql`
        INSERT INTO columns (id, title, position) VALUES (${col.id}, ${col.title}, ${col.position})
      `;
    }
  }
}

// GET /api/board - return full board state
app.get('/api/board', async (_req, res) => {
  try {
    const columns = await db.sql`
      SELECT id, title, position FROM columns ORDER BY position
    `;

    const result = [];
    for (const col of columns) {
      const cards = await db.sql`
        SELECT id, column_id, text, position, created_at FROM cards
        WHERE column_id = ${col.id}
        ORDER BY position
      `;
      result.push({
        id: col.id,
        title: col.title,
        position: col.position,
        cards: cards.map((c) => ({
          id: c.id,
          column_id: c.column_id,
          text: c.text,
          position: c.position,
          created_at: c.created_at,
        })),
      });
    }

    res.json(result);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// POST /api/cards - create a new card
app.post('/api/cards', async (req, res) => {
  const { columnId, text } = req.body;

  if (!columnId || !text) {
    return res.status(400).json({ error: 'columnId and text are required' });
  }

  // Check column exists
  const colCheck = await db.sql`SELECT id FROM columns WHERE id = ${columnId}`;
  if (colCheck.length === 0) {
    return res.status(404).json({ error: 'Column not found' });
  }

  // Get max position in column
  const maxPos = await db.sql`
    SELECT COALESCE(MAX(position), 0) as max_pos FROM cards WHERE column_id = ${columnId}
  `;

  const newCard = {
    id: crypto.randomUUID(),
    column_id: columnId,
    text,
    position: (maxPos[0].max_pos || 0) + 1,
    created_at: new Date().toISOString(),
  };

  await db.sql`
    INSERT INTO cards (id, column_id, text, position, created_at)
    VALUES (${newCard.id}, ${newCard.column_id}, ${newCard.text}, ${newCard.position}, ${newCard.created_at})
  `;

  // Broadcast
  broadcast('card-created', newCard);

  res.json(newCard);
});

// PATCH /api/cards/:id/move - move a card to a new column/position
app.patch('/api/cards/:id/move', async (req, res) => {
  const { id } = req.params;
  const { columnId, beforeId, afterId } = req.body;

  if (!columnId) {
    return res.status(400).json({ error: 'columnId is required' });
  }

  // Check card exists
  const cardCheck = await db.sql`SELECT id, column_id FROM cards WHERE id = ${id}`;
  if (cardCheck.length === 0) {
    return res.status(404).json({ error: 'Card not found' });
  }

  // Check target column exists
  const colCheck = await db.sql`SELECT id FROM columns WHERE id = ${columnId}`;
  if (colCheck.length === 0) {
    return res.status(404).json({ error: 'Column not found' });
  }

  let newPosition;

  if (beforeId) {
    // Move before a specific card
    const beforeCard = await db.sql`SELECT position FROM cards WHERE id = ${beforeId}`;
    if (beforeCard.length > 0) {
      newPosition = beforeCard[0].position - 1;
    }
  } else if (afterId) {
    // Move after a specific card
    const afterCard = await db.sql`SELECT position FROM cards WHERE id = ${afterId}`;
    if (afterCard.length > 0) {
      newPosition = afterCard[0].position + 1;
    }
  } else {
    // No anchor, place at end
    const maxPos = await db.sql`
      SELECT COALESCE(MAX(position), 0) as max_pos FROM cards WHERE column_id = ${columnId}
    `;
    newPosition = (maxPos[0].max_pos || 0) + 1;
  }

  // If new position is <= 0, set to 1
  if (newPosition <= 0) {
    newPosition = 1;
  }

  // Atomic transaction: update column_id and position
  const now = new Date().toISOString();
  await db.exec(`
    BEGIN;
    UPDATE cards SET column_id = ${columnId}, position = ${newPosition}, created_at = ${now} WHERE id = ${id};
    COMMIT;
  `);

  // Read back the updated card
  const updatedCard = await db.sql`
    SELECT id, column_id, text, position, created_at FROM cards WHERE id = ${id}
  `;

  const card = {
    id: updatedCard[0].id,
    column_id: updatedCard[0].column_id,
    text: updatedCard[0].text,
    position: updatedCard[0].position,
    created_at: updatedCard[0].created_at,
  };

  // Check for position collisions and renormalize if needed
  await renormalizeColumn(columnId);

  // Broadcast the move
  broadcast('card-moved', card);

  res.json(card);
});

// Renormalize positions in a column to avoid precision exhaustion
async function renormalizeColumn(columnId) {
  const cards = await db.sql`
    SELECT id, position FROM cards WHERE column_id = ${columnId} ORDER BY position
  `;

  // Check for duplicate positions
  const positions = cards.map((c) => c.position);
  const uniquePositions = new Set(positions);
  if (uniquePositions.size === positions.length) {
    return; // No collisions, no need to renormalize
  }

  // Renormalize: assign sequential positions 1, 2, 3, ...
  const updates = cards.map((c, i) => i + 1);
  for (let i = 0; i < cards.length; i++) {
    await db.sql`
      UPDATE cards SET position = ${updates[i]} WHERE id = ${cards[i].id} AND column_id = ${columnId}
    `;
  }

  // Broadcast the corrected order
  const updatedCards = await db.sql`
    SELECT id, column_id, text, position, created_at FROM cards
    WHERE column_id = ${columnId} ORDER BY position
  `;
