    // Move after a specific card
    const afterCard = await db.exec(`SELECT position FROM cards WHERE id = '${sqlEscape(afterId)}'`);
    if (afterCard[0].rows.length > 0) {
      newPosition = Number(afterCard[0].rows[0].position) + 1;
    }
