  // If new position is <= 0, set to 1
  if (newPosition <= 0) {
    newPosition = 1;
  }

  // Atomic transaction: update column_id and position
  const now = new Date().toISOString();
  await db.exec(`
    BEGIN;
    UPDATE cards SET column_id = ${columnId}, position = ${newPosition}, created_at = ${now} WHERE id = ${id};
    COMMIT;
  `);

  // Read back the updated card
  const updatedCard = await db.sql`
    SELECT id, column_id, text, position, created_at FROM cards WHERE id = ${id}
  `;

  const card = {
    id: updatedCard[0].id,
    column_id: updatedCard[0].column_id,
    text: updatedCard[0].text,
    position: updatedCard[0].position,
    created_at: updatedCard[0].created_at,
  };

  // Check for position collisions and renormalize if needed
  await renormalizeColumn(columnId);

  // Broadcast the move
  broadcast('card-moved', card);

  res.json(card);
});

// Renormalize positions in a column to avoid precision exhaustion
async function renormalizeColumn(columnId) {
  const cards = await db.sql`
    SELECT id, position FROM cards WHERE column_id = ${columnId} ORDER BY position
  `;

  // Check for duplicate positions
  const positions = cards.map((c) => c.position);
  const uniquePositions = new Set(positions);
  if (uniquePositions.size === positions.length) {
    return; // No collisions, no need to renormalize
  }

  // Renormalize: assign sequential positions 1, 2, 3, ...
  const updates = cards.map((c, i) => i + 1);
  for (let i = 0; i < cards.length; i++) {
    await db.sql`
      UPDATE cards SET position = ${updates[i]} WHERE id = ${cards[i].id} AND column_id = ${columnId}
    `;
  }

  // Broadcast the corrected order
  const updatedCards = await db.sql`
    SELECT id, column_id, text, position, created_at FROM cards
    WHERE column_id = ${columnId} ORDER BY position
  `;
  broadcast('column-renormalized', {
    columnId,
    cards: updatedCards.map((c) => ({
      id: c.id,
      column_id: c.column_id,
      text: c.text,
      position: c.position,
      created_at: c.created_at,
    })),
  });
}

