{"content": "* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  padding: 20px;
}

#app {
  max-width: 1400px;
  margin: 0 auto;
}

#app h1 {
  color: #fff;
  font-size: 24px;
  margin-bottom: 20px;
  font-weight: 700;
}

.board {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  align-items: flex-start;
  padding-bottom: 20px;
}

.column {
  background: #ebecf0;
  border-radius: 8px;
  min-width: 280px;
  max-width: 280px;
  padding: 12px;
  flex-shrink: 0;
}

.column-header {
  font-weight: 600;
  font-size: 14px;
  color: #172b4d;
  padding: 8px 4px;
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-list {
  min-height: 40px;
}

.card {
  background: #fff;
  border-radius: 4px;
  padding: 8px 12px;
  margin-bottom: 8px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  cursor: grab;
  font-size: 14px;
  color: #172b4d;
  transition: background 0.15s, opacity 0.15s;
  word-wrap: break-word;
}

.card:hover {
  background: #f4f5f7;
}

.card.dragging {
  opacity: 0.5;
  cursor: grabbing;
}

.card.drag-over {
  border-top: 2px solid #0079bf;
}

.add-card-form {
  margin-top: 8px;
}

.add-card-form input {
  width: 100%;
  padding: 8px 10px;
  border: 2px solid #026aa7;
  border-radius: 4px;
  font-size: 14px;
  outline: none;
}

.add-card-form button {
  margin-top: 6px;
  width: 100%;
  padding: 8px;
  background: #0079bf;
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
