      inserted = true;
      break;
    }
  }
  if (!inserted) {
    targetCol.cards.push(movedCard);
  }

  renderBoard();
}

// ---- Init ----

async function init() {
  boardState = await fetchBoard();
  renderBoard();
  connectSSE();
}

init();
