  );
  broadcast('column-renormalized', {
    columnId,
    cards: updatedCardsResult[0].rows.map((c) => ({
      id: c.id,
      column_id: c.column_id,
      text: c.text,
      position: Number(c.position),
      created_at: c.created_at,
    })),
  });
}

// SSE endpoint
