      const columns = rows(colResult);

      const boardState = [];
      for (const col of columns) {
        const cardResult = await db.sql`
          SELECT id, column_id, text, position, created_at
          FROM cards WHERE column_id = ${col.id} ORDER BY position
        `;
        boardState.push({
          id: col.id,
          title: col.title,
          position: col.position,
