      res.write(`event: board-sync\ndata: ${JSON.stringify(boardState)}\n\n`);
    } catch (e) {
      console.error('Error sending initial board state:', e);
    }
  })();

  clients.push(res);

  req.on('close', () => {
    clients = clients.filter((c) => c !== res);
  });
});

