  if (newPosition <= 0) {
    newPosition = 1;
  }

  // Atomic transaction: update column_id and position
  const now = new Date().toISOString();
  await db.exec('BEGIN');
  try {
    await db.sql`UPDATE cards SET column_id = ${columnId}, position = ${newPosition}, created_at = ${now} WHERE id = ${id}`;
