  movedCard.column_id = targetColumnId;

  let inserted = false;
  for (let i = 0; i < targetCol.cards.length; i++) {
    if (optimisticPosition < targetCol.cards[i].position) {
      targetCol.cards.splice(i, 0, movedCard);
      inserted = true;
      break;
    }
  }
  if (!inserted) {
    targetCol.cards.push(movedCard);
  }

  renderBoard();
}

