  // Renormalize: assign sequential positions 1, 2, 3, ...
  for (let i = 0; i < cards.length; i++) {
    await db.exec(
      `UPDATE cards SET position = ${i + 1} WHERE id = '${sqlEscape(cards[i].id)}' AND column_id = '${sqlEscape(columnId)}'`
