// Optimistic move: update local state immediately, then reconcile from SSE
function optimisticMove(cardId, sourceColumnId, sourceIndex, targetColumnId, beforeId, afterId) {
  let movedCard = null;
  let sourceCol = null;

  for (const col of boardState) {
